import copy

import pytest
from hypothesis import given
from hypothesis.strategies import sampled_from
import hypothesis.strategies as st

from intervals import merge_intervals


def point_set(intervals):
    pts = set()
    for s, e in intervals:
        pts.update(range(s, e + 1))
    return pts


def reference_merge(intervals):
    for s, e in intervals:
        if s > e:
            raise ValueError
    if not intervals:
        return []
    ivs = sorted(intervals)
    out = [ivs[0]]
    for s, e in ivs[1:]:
        ps, pe = out[-1]
        if s <= pe:  # overlap or touch (share a point); adjacent s == pe+1 stays separate
            out[-1] = (ps, max(pe, e))
        else:
            out.append((s, e))
    return out


small_int = st.integers(min_value=-10, max_value=10)
valid_interval = st.builds(
    lambda a, b: (min(a, b), max(a, b)), small_int, small_int
)
valid_lists = st.lists(valid_interval, max_size=8)


# --- concrete spec examples ---

def test_example_basic():
    assert merge_intervals([(1, 3), (2, 6), (8, 10), (15, 18)]) == [(1, 6), (8, 10), (15, 18)]


def test_example_touching_merges():
    assert merge_intervals([(1, 3), (3, 5)]) == [(1, 5)]


def test_example_adjacent_stays_separate():
    assert merge_intervals([(1, 3), (4, 5)]) == [(1, 3), (4, 5)]


def test_example_unsorted_input_sorted_output():
    assert merge_intervals([(5, 7), (1, 2)]) == [(1, 2), (5, 7)]


def test_example_empty():
    assert merge_intervals([]) == []


def test_example_invalid_raises():
    with pytest.raises(ValueError):
        merge_intervals([(3, 1)])


# --- targeted defect probes ---

def test_contained_interval_is_absorbed():
    # Catches failure to take max(end): [(1,10),(2,3)] must stay [(1,10)], not [(1,3)]
    assert merge_intervals([(1, 10), (2, 3)]) == [(1, 10)]


def test_contained_interval_unsorted_is_absorbed():
    assert merge_intervals([(2, 3), (1, 10)]) == [(1, 10)]


def test_multiple_contained_intervals_absorbed():
    assert merge_intervals([(1, 10), (2, 3), (4, 5), (6, 7)]) == [(1, 10)]


def test_overlapping_extending_end():
    assert merge_intervals([(1, 5), (2, 10)]) == [(1, 10)]


def test_same_start_contained():
    assert merge_intervals([(1, 10), (1, 2)]) == [(1, 10)]


def test_same_end_contained():
    assert merge_intervals([(1, 10), (9, 10)]) == [(1, 10)]


def test_touching_chain_collapses_transitively():
    assert merge_intervals([(1, 2), (2, 3), (3, 4)]) == [(1, 4)]


def test_overlap_chain_collapses_transitively():
    assert merge_intervals([(1, 3), (2, 4), (3, 5)]) == [(1, 5)]


def test_single_point_valid_and_touching():
    assert merge_intervals([(2, 2)]) == [(2, 2)]
    assert merge_intervals([(1, 2), (2, 2)]) == [(1, 2)]
    assert merge_intervals([(2, 2), (3, 3)]) == [(2, 2), (3, 3)]


def test_duplicates_collapse():
    assert merge_intervals([(1, 3), (1, 3)]) == [(1, 3)]
    assert merge_intervals([(5, 5), (5, 5), (5, 5)]) == [(5, 5)]


def test_negative_and_zero_intervals():
    assert merge_intervals([(-5, -3), (-4, -2)]) == [(-5, -2)]
    assert merge_intervals([(-3, -3), (-2, -2)]) == [(-3, -3), (-2, -2)]
    assert merge_intervals([(-2, 0), (0, 2)]) == [(-2, 2)]


def test_invalid_anywhere_raises():
    with pytest.raises(ValueError):
        merge_intervals([(1, 2), (5, 4)])
    with pytest.raises(ValueError):
        merge_intervals([(5, 4), (1, 2)])
    with pytest.raises(ValueError):
        merge_intervals([(0, 0), (3, 1), (1, 2)])


def test_input_not_mutated():
    data = [(5, 7), (1, 10), (2, 3)]
    snapshot = copy.deepcopy(data)
    merge_intervals(data)
    assert data == snapshot


def test_input_tuples_not_mutated_and_output_is_new():
    data = [(1, 3), (2, 4)]
    inner0 = data[0]
    out = merge_intervals(data)
    assert out is not data
    assert data[0] is inner0
    assert all(isinstance(iv, tuple) for iv in out)


def test_output_sorted_and_strictly_disjoint():
    out = merge_intervals([(5, 7), (1, 3), (4, 4), (8, 9)])
    starts = [s for s, _ in out]
    assert starts == sorted(starts)
    for (ps, pe), (s, e) in zip(out, out[1:]):
        assert s > pe


# --- property-based tests ---

@given(valid_lists)
def test_property_matches_reference_model(intervals):
    assert merge_intervals(list(intervals)) == reference_merge(list(intervals))


@given(valid_lists)
def test_property_coverage_preserved(intervals):
    out = merge_intervals(list(intervals))
    assert point_set(out) == point_set(intervals)


@given(valid_lists)
def test_property_output_sorted_and_disjoint(intervals):
    out = merge_intervals(list(intervals))
    for i in range(len(out)):
        s, e = out[i]
        assert s <= e
        assert isinstance(out[i], tuple)
    for i in range(1, len(out)):
        assert out[i][0] > out[i - 1][1]
    starts = [s for s, _ in out]
    assert starts == sorted(starts)


@given(valid_lists)
def test_property_touching_points_share_output_interval(intervals):
    # any two consecutive integers both covered must lie in same output interval
    out = merge_intervals(list(intervals))
    covered = point_set(intervals)
    for p in list(covered):
        if p + 1 in covered:
            holders_p = [iv for iv in out if iv[0] <= p <= iv[1]]
            holders_q = [iv for iv in out if iv[0] <= p + 1 <= iv[1]]
            assert len(holders_p) == 1
            assert holders_p == holders_q


@given(valid_lists)
def test_property_adjacent_gap_stays_separate(intervals):
    # gap point not covered => its neighbours cannot be in same output interval
    out = merge_intervals(list(intervals))
    covered = point_set(intervals)
    if not covered:
        return
    lo, hi = min(covered), max(covered)
    for g in range(lo, hi + 1):
        if g not in covered:
            left = [iv for iv in out if iv[0] <= g - 1 <= iv[1]]
            right = [iv for iv in out if iv[0] <= g + 1 <= iv[1]]
            if left and right:
                assert left[0] is not right[0]


@given(valid_lists)
def test_property_idempotent(intervals):
    once = merge_intervals(list(intervals))
    assert merge_intervals(list(once)) == once


@given(valid_lists)
def test_property_order_independence(intervals):
    out1 = merge_intervals(list(intervals))
    out2 = merge_intervals(list(reversed(intervals)))
    assert out1 == out2


@given(st.lists(valid_interval, min_size=1, max_size=6))
def test_property_output_is_minimal_cover(intervals):
    # every output interval must be justified: removing it loses coverage,
    # and no two outputs can be merged (they are strictly disjoint w/ gap >= 1)
    out = merge_intervals(list(intervals))
    full = point_set(intervals)
    assert point_set(out) == full
    for i, iv in enumerate(out):
        rest = out[:i] + out[i + 1:]
        assert point_set(rest) != full
    for a, b in zip(out, out[1:]):
        assert b[0] > a[1]
        assert b[0] - a[1] >= 2 or (a[1] + 1 not in full and b[0] - 1 not in full) or True
        # stronger: the gap point a[1]+1 .. b[0]-1 contains an uncovered point
        assert any(p not in full for p in range(a[1], b[0] + 1))


@given(st.lists(valid_interval, max_size=5), st.integers(min_value=-10, max_value=10), st.integers(min_value=-10, max_value=10))
def test_property_invalid_input_raises(intervals, a, b):
    bad = (max(a, b) + 1, min(a, b))  # start > end guaranteed
    assert bad[0] > bad[1]
    data = list(intervals) + [bad]
    with pytest.raises(ValueError):
        merge_intervals(data)


@given(st.sampled_from([[(1, 10), (2, 3)], [(0, 5), (1, 1), (2, 2)], [(-5, 5), (-3, -1), (0, 0)], [(1, 2), (1, 5), (1, 3)]]))
def test_property_container_never_shrinks(intervals):
    out = merge_intervals(list(intervals))
    big = max(e for _, e in intervals)
    small = min(s for s, _ in intervals)
    assert out[0][0] == small
    assert out[-1][1] == big
    assert point_set(out) == point_set(intervals)
